package com.analyzercoder.interfaces.rest;
import com.analyzercoder.application.intelligence.CodeGraphService;import com.analyzercoder.application.intelligence.IntelligenceService;import com.analyzercoder.domain.repository.CodeRepositoryId;import com.analyzercoder.security.*;import jakarta.servlet.http.HttpServletRequest;import java.util.UUID;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/repositories/{repoId}/codegraph")public class CodeGraphController{private final CodeGraphService service;private final AccessControlService access;public CodeGraphController(CodeGraphService service,AccessControlService access){this.service=service;this.access=access;}@PostMapping("/build")public CodeGraphService.Artifact build(@PathVariable UUID repoId,HttpServletRequest request){access.require(SecurityContext.account(request),CodeRepositoryId.of(repoId),RepositoryPermission.MAINTAIN);return service.build(repoId);}@GetMapping("/latest")public CodeGraphService.Artifact latest(@PathVariable UUID repoId,HttpServletRequest request){access.require(SecurityContext.account(request),CodeRepositoryId.of(repoId),RepositoryPermission.READ);return service.latest(repoId);}@GetMapping("/impact")public IntelligenceService.GraphResult impact(@PathVariable UUID repoId,@RequestParam String symbol,@RequestParam(defaultValue="3")int depth,HttpServletRequest request){access.require(SecurityContext.account(request),CodeRepositoryId.of(repoId),RepositoryPermission.READ);return service.impact(repoId,symbol,depth);}}
